using System;
using System.Linq;
using System.Reflection;
using KingdomEnhancedMod;
internal static class Program {
 static int passed,failed;
 static void Check(bool b,string why){if(b)passed++;else{failed++;Console.WriteLine("FAIL "+why);}}
 static bool Clone(PalaceLayoutRecipe recipe,out object clone,out string reason){var all=typeof(PalaceLand12Runtime).GetMethods(BindingFlags.Static|BindingFlags.NonPublic).Where(m=>m.Name=="TryGetReusableClone").ToArray();var m=all.OrderByDescending(x=>x.GetParameters().Length).First();object[] args=m.GetParameters().Length==5?new object[]{new BiomeHolder(),7UL,recipe,null,null}:new object[]{new BiomeHolder(),7UL,null,null};bool ok=(bool)m.Invoke(null,args);clone=args[^2];reason=(string)args[^1];return ok;}
 static bool Resolve(out PalaceLayoutRecipe recipe){var method=typeof(PalaceLand12Runtime).GetMethod("TryResolveConfigRecipe",BindingFlags.Static|BindingFlags.NonPublic);object[] args={new CampaignSaveData(),null,null};bool ok=(bool)method.Invoke(null,args);recipe=(PalaceLayoutRecipe)args[1];return ok;}
 static int Main(){Check(Clone(PalaceLayoutRecipe.Known44,out var old,out _),"known44 initial clone");Check(!Clone(PalaceLayoutRecipe.Capital400,out _,out _),"published44 cannot be reinterpreted as400");Check(Clone(PalaceLayoutRecipe.Known44,out var again,out _)&&ReferenceEquals(old,again),"same recipe reuses same clone");Check(PalaceLand12Runtime.ConfigCache.Allocations==1,"one native clone allocation");if(typeof(PalaceLand12Runtime).GetMethod("TryResolveConfigRecipe",BindingFlags.Static|BindingFlags.NonPublic)!=null){PalaceLand12Runtime._handoff=new(){Recipe=PalaceLayoutRecipe.Capital400,TripId="trip"};PalaceTripContext.Record=new(){Version=4,TripId="trip",DestinationLayout=PalaceLayoutRecipe.Capital400};Check(Resolve(out var r)&&ReferenceEquals(r,PalaceLayoutRecipe.Capital400),"active v4 token key consumed before Playing");PalaceTripContext.Record.DestinationLayout=PalaceLayoutRecipe.Known44;Check(!Resolve(out _),"token/trip key mismatch refused");PalaceTripContext.Record.Version=2;Check(!Resolve(out _),"unknown old version cannot inherit token400");PalaceLand12Runtime._handoff=null;PalaceTripContext.Record=new(){Version=3,TripId="legacy"};PalaceDestinationAdmission.SavedProof=false;Check(!Resolve(out _),"cold v3 cannot imply44 without actual proof");PalaceDestinationAdmission.SavedProof=true;Check(Resolve(out r)&&ReferenceEquals(r,PalaceLayoutRecipe.Known44),"strict legacy44 evidence selects44");PalaceTripContext.Record=new(){Version=4,TripId="new",DestinationLayout=PalaceLayoutRecipe.Capital400};Check(Resolve(out r)&&ReferenceEquals(r,PalaceLayoutRecipe.Capital400),"cold v4 consumes explicit key with saved proof");}Console.WriteLine($"D config exact production methods: passed={passed} failed={failed}");return failed==0?0:1;}
}
